<?php
declare(strict_types=1);

namespace SopuCoder\Domain\Payments;

enum PaymentStatus: string
{
    case PENDING    = 'pending';
    case PROCESSING = 'processing';
    case COMPLETED  = 'completed';
    case FAILED     = 'failed';
    case REFUNDED   = 'refunded';

    public function label(): string
    {
        return match($this) {
            self::PENDING    => 'Awaiting Payment',
            self::PROCESSING => 'Payment in Progress',
            self::COMPLETED  => 'Payment Completed',
            self::FAILED     => 'Payment Failed',
            self::REFUNDED   => 'Payment Refunded',
        };
    }

    public function canTransitionTo(self $next): bool
    {
        return match($this) {
            self::PENDING    => in_array($next, [self::PROCESSING, self::FAILED], true),
            self::PROCESSING => in_array($next, [self::COMPLETED, self::FAILED], true),
            self::COMPLETED  => $next === self::REFUNDED,
            self::FAILED, self::REFUNDED => false,
        };
    }
}
