<?php
declare(strict_types=1);

namespace SopuCoder\Pipelines;

use Closure;

final class Pipeline
{
    /** @var array<callable(mixed, Closure): mixed> */
    private array $pipes = [];

    /**
     * Adds middleware pipes to the execution stack.
     *
     * @param array<callable(mixed, Closure): mixed> $pipes
     */
    public function pipe(array $pipes): self
    {
        $this->pipes = array_merge($this->pipes, $pipes);
        return $this;
    }

    /**
     * Runs the passable payload through the pipeline and sends it to the destination.
     *
     * @param mixed $passable
     * @param Closure(mixed): mixed $destination
     * @return mixed
     */
    public function send(mixed $passable, Closure $destination): mixed
    {
        $pipeline = array_reduce(
            array_reverse($this->pipes),
            function (Closure $next, callable $pipe) {
                return function (mixed $passable) use ($pipe, $next) {
                    return $pipe($passable, $next);
                };
            },
            $destination
        );

        return $pipeline($passable);
    }
}
